     1	// Tiered discount. Orders over the threshold get the higher rate.
     2	const THRESHOLD_MINOR = 10_000;
     3	
     4	export function discountMinor(subtotalMinor, memberSince) {
     5	  const rate = subtotalMinor > THRESHOLD_MINOR ? 0.1 : 0.05;
     6	  const years = new Date('2026-09-01').getFullYear() - memberSince;
     7	  const loyalty = Math.min(years, 5) * 0.01;
     8	  return Math.round(subtotalMinor * (rate + loyalty));
     9	}
